fn find_first_occurrence(arr: &Vec<i32>, target: i32) -> Option<usize> {
    let mut lo: usize = 0;
    let mut hi: usize = arr.len(); // search in [lo, hi)
    let mut ans: Option<usize> = None;

    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        let v = arr[mid];

        if v < target {
            lo = mid + 1;
        } else if v > target {
            hi = mid;
        } else {
            // v == target: record candidate and continue left to find first occurrence
            ans = Some(mid);
            hi = mid;
        }
    }

    ans
}